function canOpenerWin(nums: number[]): boolean {
  // lead the mover can get on nums[i..j]
  const lead = (i: number, j: number): number => {
    if (i === j) return nums[i];
    return Math.max(nums[i] - lead(i + 1, j), nums[j] - lead(i, j - 1));
  };
  return lead(0, nums.length - 1) >= 0;
}

