function canOpenerWin(nums: number[]): boolean {
  const n = nums.length;
  const dp = new Array<number>(n).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    dp[i] = nums[i];
    for (let j = i + 1; j < n; j++) {
      // dp[j] still holds range i+1..j, dp[j-1] already holds i..j-1
      dp[j] = Math.max(nums[i] - dp[j], nums[j] - dp[j - 1]);
    }
  }
  return dp[n - 1] >= 0;
}

