class Solution:
    def canOpenerWin(self, nums: List[int]) -> bool:
        n = len(nums)
        dp = [0] * n
        for i in range(n - 1, -1, -1):
            dp[i] = nums[i]
            for j in range(i + 1, n):
                a, b = nums[i] - dp[j], nums[j] - dp[j - 1]
                dp[j] = a if a > b else b
        return dp[n - 1] >= 0

